     1	import Image from "next/image";
     2	import Link from "next/link";
     3	import { CubeUnicorn } from "@/components/cube-unicorn";
     4	import { MotionRoot } from "@/components/portfolio-motion";
     5	import {
     6	  capabilities,
     7	  projects,
     8	  socialLinks,
     9	  testimonials,
    10	  type Project,
    11	} from "@/lib/portfolio";
    12	
    13	function SiteNav() {
    14	  return (
    15	    <header className="site-header">
    16	      <nav className="site-nav" aria-label="Primary navigation">
    17	        <Link className="wordmark" href="#top" aria-label="Irfan Hossain, home">
    18	          Irfan Hossain
    19	        </Link>
    20	        <div className="nav-links">
    21	          <Link href="#work">Work</Link>
    22	          <Link href="#about">About</Link>
    23	          <Link href="#contact">Contact</Link>
