    27	          <div>
    28	            <Link href="#work">Work</Link>
    29	            <Link href="#about">About</Link>
    30	            <Link href="#contact">Contact</Link>
    31	          </div>
    32	        </details>
    33	        <Link
    34	          className="button button-primary nav-hire"
    35	          href={socialLinks[0].href}
    36	        >
    37	          Hire Me
    38	        </Link>
    39	      </nav>
    40	    </header>
    41	  );
    42	}
    43	
    44	function Hero() {
    45	  return (
    46	    <section className="hero" id="top" aria-labelledby="hero-title">
    47	      <p className="eyebrow">Full-Stack Developer · Dhaka, Bangladesh</p>
    48	      <h1 id="hero-title" className="max-w-6xl">I build digital products and physical systems.</h1>
    49	      <div className="hero-actions">
    50	        <Link className="button button-primary" href={socialLinks[0].href}>
    51	          Hire Me
    52	        </Link>
    53	        <Link className="button button-secondary" href="#work">
    54	          Selected Work
    55	        </Link>
    56	      </div>
    57	      <CubeUnicorn />
    58	    </section>
    59	  );
    60	}
    61	
    62	function CapabilityMarquee() {
    63	  return (
    64	    <section className="capability-strip" aria-label="Fields of work">
    65	      <div className="marquee-track">
    66	        {[...capabilities, ...capabilities].map((capability, index) => (
    67	          <span
    68	            key={`${capability}-${index}`}
    69	            aria-hidden={index >= capabilities.length}
    70	          >
    71	            {capability}
    72	          </span>
    73	        ))}
    74	      </div>
    75	    </section>
    76	  );
    77	}
    78	
    79	function ProjectLinks({ project }: { project: Project }) {
    80	  return (
    81	    <div className="project-links">
    82	      <Link href={project.href} target="_blank" rel="noreferrer">
    83	        Repository <span aria-hidden="true">↗</span>
    84	      </Link>
    85	      {project.demo ? (
    86	        <Link href={project.demo} target="_blank" rel="noreferrer">
    87	          Live product <span aria-hidden="true">↗</span>
    88	        </Link>
    89	      ) : null}
    90	    </div>
    91	  );
    92	}
    93	
    94	function ProjectBento({ projects }: { projects: Project[] }) {
    95	  return (
    96	    <section className="chapter" id="work" aria-labelledby="work-title">
    97	      <div className="section-heading">
    98	        <p className="eyebrow">Selected work</p>
    99	        <h2 id="work-title">Products built across screens and circuits.</h2>
   100	      </div>
   101	      <div className="project-bento grid grid-cols-1 md:grid-cols-12 md:grid-rows-2 grid-flow-dense">
   102	        {projects.map((project) => (
   103	          <article
   104	            className={`project-card tone-${project.tone} ${project.gridClass}`}
   105	            key={project.slug}
   106	          >
   107	            <Link
   108	              className="project-media media-link"
   109	              href={project.demo ?? project.href}
   110	              target="_blank"
   111	              rel="noreferrer"
   112	              aria-label={`View ${project.title}`}
   113	            >
   114	              <Image
   115	                src={project.image}
   116	                alt={project.imageAlt}
   117	                fill
   118	                sizes="(max-width: 767px) 100vw, 50vw"
   119	                data-project-media
   120	              />
   121	            </Link>
   122	            <div className="project-copy">
   123	              <p className="eyebrow">{project.field}</p>
   124	              <h3>{project.title}</h3>
   125	              <p>{project.summary}</p>
   126	              <ProjectLinks project={project} />
   127	            </div>
   128	          </article>
   129	        ))}
   130	      </div>
   131	    </section>
   132	  );
   133	}
   134	
   135	function FieldStatement() {
   136	  return (
   137	    <section
   138	      className="field-statement"
   139	      id="about"
   140	      aria-labelledby="about-title"
   141	    >
   142	      <p className="eyebrow">From interface to hardware</p>
   143	      <h2 id="about-title">
   144	        I take ideas from screen{" "}
   145	        <span className="inline-image">
   146	          <Image src="/projects/bteb-flow.png" alt="" fill sizes="160px" />
   147	        </span>{" "}
   148	        to circuit{" "}
   149	        <span className="inline-image">
   150	          <Image
   151	            src="/projects/soldering-station.jpg"
   152	            alt=""
   153	            fill
   154	            sizes="160px"
   155	          />
   156	        </span>{" "}
   157	        and build the systems between.
   158	      </h2>
   159	      <p className="field-copy">
   160	        Full-Stack Developer building scalable software, intuitive experiences,
   161	        embedded systems, and IoT products.
   162	      </p>
   163	    </section>
   164	  );
   165	}
   166	
   167	function ProjectAccordion({ projects }: { projects: Project[] }) {
   168	  return (
   169	    <div className="project-accordion" aria-label="Explore projects by field">
   170	      {projects.map((project, index) => (
   171	        <details
   172	          className={`accordion-item tone-${project.tone}`}
   173	          key={project.slug}
   174	          open={index === 0}
   175	        >
   176	          <summary>
   177	            <span>{project.field}</span>
   178	            <strong>{project.title}</strong>
   179	          </summary>
   180	          <div className="accordion-copy">
   181	            <p>{project.summary}</p>
   182	            <Link href={project.href} target="_blank" rel="noreferrer">
   183	              Explore project <span aria-hidden="true">↗</span>
   184	            </Link>
   185	          </div>
   186	        </details>
   187	      ))}
   188	    </div>
   189	  );
   190	}
   191	
   192	function ProjectStack({ projects }: { projects: Project[] }) {
   193	  return (
   194	    <section
   195	      className="chapter project-stories"
   196	      aria-labelledby="stories-title"
   197	    >
   198	      <div className="section-heading">
   199	        <p className="eyebrow">How the work takes shape</p>
   200	        <h2 id="stories-title">
   201	          One practice, from product decisions to precise control.
   202	        </h2>
   203	      </div>
   204	      <ProjectAccordion projects={projects} />
   205	      <div className="project-stack" data-stack>
   206	        {projects.map((project) => (
   207	          <article
   208	            className={`stack-card tone-${project.tone}`}
   209	            data-stack-card
   210	            key={project.slug}
   211	          >
   212	            <div className="stack-copy">
   213	              <p className="eyebrow">{project.field}</p>
   214	              <h3>{project.title}</h3>
   215	              <p>{project.summary}</p>
   216	              <ProjectLinks project={project} />
   217	            </div>
   218	            <div className="stack-media">
   219	              <Image
   220	                src={project.image}
   221	                alt={project.imageAlt}
   222	                fill
   223	                sizes="(max-width: 767px) 100vw, 55vw"
   224	                data-project-media
   225	              />
   226	            </div>
   227	          </article>
   228	        ))}
   229	      </div>
   230	    </section>
   231	  );
   232	}
   233	
   234	function TestimonialStructure() {
   235	  return testimonials.length ? <section aria-label="Testimonials" /> : null;
   236	}
   237	
   238	function ContactSection({ links }: { links: typeof socialLinks }) {
