   240	    <section
   241	      className="contact-section"
   242	      id="contact"
   243	      aria-labelledby="contact-title"
   244	    >
   245	      <p className="eyebrow">
   246	        Available for internships and freelance projects.
   247	      </p>
   248	      <h2 id="contact-title">Have something worth building?</h2>
   249	      <p>Let&apos;s make the product, system, or prototype real.</p>
   250	      <Link className="button button-primary" href={links[0].href}>
   251	        Hire Me
   252	      </Link>
   253	    </section>
   254	  );
   255	}
   256	
   257	function SiteFooter({ links }: { links: typeof socialLinks }) {
